using System;
namespace DomainConsole.Shared {
 public static class ExecutionDiagnosis {
  public static string Code(int code)=>code+" (0x"+unchecked((uint)code).ToString("X8")+")";
  public static string Explain(int code){switch(unchecked((uint)code)){case 12002:case 0x80072EE2:return "Истекло время сетевого запроса. Проверьте источник восстановления/обновлений, доступ из SYSTEM, разрешение доступа в Kerio, прокси и политики. Конкретный сервер этим кодом не определяется.";case 0x80240034:return "Не удалось скачать обновление. Проверьте содержимое WSUS, сеть и кэш загрузок.";case 0x80070570:return "Файл или каталог повреждён и нечитаем. Возможны повреждение загрузки, хранилища компонентов или диска.";case 0xc0000005:return "Нарушение доступа к памяти процесса. По этому коду нельзя определить виновный компонент.";case 0x80240022:return "Сбой операции обновления. Общий код WUA не устанавливает причину; проверьте конкретное обновление и WindowsUpdate.log.";case 0x800F081F:return "Не найдены исходные файлы восстановления. Проверьте подходящий источник и индекс образа.";case 5:case 0x80070005:return "Отказано в доступе. Проверьте права и разрешения.";default:return "Команда завершилась с ненулевым кодом. Подробности смотрите в выводе и журналах; код зависит от запущенной программы.";}}
 }
}
